        { "action": "visible", "selector": "#addItemForm" },
        { "action": "visible", "selector": "#calculateBtn" }
      ],
      "apiChecks": [
        { "requests": [ { "method": "GET", "path": "/" } ], "statuses": [200] }
      ]
    },
    {
      "name": "POST /api/quote بحالة صحيحة يرجع 200 بالحقول الأربعة فقط: 5748 و 862 و 500 و 5386",
      "steps": [
        { "action": "visible", "selector": "#calculateBtn" }
      ],
      "apiChecks": [
        {
          "requests": [
