            }
          ],
          "statuses": [200]
        }
      ]
    },
    {
      "name": "تقريب النصف للأعلى: 125 سنت بخصم 10% يعطي discountCents=13 و totalCents=112 عبر الواجهة و API",
      "steps": [
        { "action": "fill", "selector": "#sku", "value": "R-1" },
        { "action": "fill", "selector": "#unitPrice", "value": "125" },
        { "action": "fill", "selector": "#quantity", "value": "1" },
        { "action": "click", "selector": "#addItemBtn" },
        { "action": "count", "selector": ".item-row", "value": 1 },
