        { "action": "textExact", "selector": "#totalCents", "value": "112" }
      ],
      "apiChecks": [
        {
          "requests": [
            {
              "method": "POST",
              "path": "/api/quote",
              "body": "{\"items\":[{\"sku\":\"R-1\",\"unitPriceCents\":125,\"quantity\":1}],\"discountPercent\":10,\"shippingCents\":0}",
              "expectedJson": { "subtotalCents": 125, "discountCents": 13, "shippingCents": 0, "totalCents": 112 }
            }
          ],
          "statuses": [200]
        }
      ]
    },
    {
      "name": "رفض المدخلات المخالفة و JSON المعطوب: 400 مع {\"error\":\"invalid\"} في كل الحالات",
      "steps": [
        { "action": "visible", "selector": "#calculateBtn" }
      ],
      "apiChecks": [
        {
          "requests": [
            { "method": "POST", "path": "/api/quote", "body": "{\"items\":[],\"discountPercent\":0,\"shippingCents\":0}", "expectedJson": { "error": "invalid" } },
            { "method": "POST", "path": "/api/quote", "body": "{\"items\":[{\"sku\":\"A-1\",\"unitPriceCents\":100,\"quantity\":1},{\"sku\":\"A-1\",\"unitPriceCents\":200,\"quantity\":1}],\"discountPercent\":0,\"shippingCents\":0}", "expectedJson": { "error": "invalid" } },
            { "method": "POST", "path": "/api/quote", "body": "{\"items\":[{\"sku\":\"   \",\"unitPriceCents\":100,\"quantity\":1}],\"discountPercent\":0,\"shippingCents\":0}", "expectedJson": { "error": "invalid" } },
            { "method": "POST", "path": "/api/quote", "body": "{\"items\":[{\"sku\":\"A-1\",\"unitPriceCents\":\"1250\",\"quantity\":1}],\"discountPercent\":0,\"shippingCents\":0}", "expectedJson": { "error": "invalid" } }
          ],
          "statuses": [400, 400, 400, 400]
        },
        {
