            { "method": "POST", "path": "/api/quote", "body": "{\"items\":[{\"sku\":\"A-1\",\"unitPriceCents\":100,\"quantity\":0}],\"discountPercent\":0,\"shippingCents\":0}", "expectedJson": { "error": "invalid" } },
