          ],
          "statuses": [400, 400, 400, 400]
        },
        {
          "requests": [
            { "method": "POST", "path": "/api/quote", "body": "{\"items\":[{\"sku\":\"A-1\",\"unitPriceCents\":100,\"quantity\":1}],\"discountPercent\":101,\"shippingCents\":0}", "expectedJson": { "error": "invalid" } },
