            { "method": "POST", "path": "/api/quote", "body": "{\"items\":[{\"sku\":\"A-1\",\"unitPriceCents\":100,\"quantity\":1}],\"discountPercent\":0,\"shippingCents\":1000001}", "expectedJson": { "error": "invalid" } },
            { "method": "POST", "path": "/api/quote", "body": "{\"items\":[{\"sku\":\"A-1\",\"unitPriceCents\":10000000,\"quantity\":101}],\"discountPercent\":0,\"shippingCents\":0}", "expectedJson": { "error": "invalid" } }
          ],
          "statuses": [400, 400, 400, 400]
        },
        {
          "requests": [
            { "method": "POST", "path": "/api/quote", "body": "{bad", "expectedJson": { "error": "invalid" } }
          ],
          "statuses": [400]
        }
      ]
    },
    {
      "name": "رحلة المستخدم: إضافة أصناف وحساب المجاميع وحذف صنف ورسالة خطأ عربية عند إرسال قيمة غير صالحة",
