        { "action": "fill", "selector": "#sku", "value": "KB-003" },
        { "action": "fill", "selector": "#unitPrice", "value": "10000001" },
        { "action": "fill", "selector": "#quantity", "value": "1" },
        { "action": "click", "selector": "#addItemBtn" },
        { "action": "click", "selector": "#calculateBtn" },
        { "action": "visible", "selector": "#errorBox" },
        { "action": "text", "selector": "#errorMsg", "value": "بيانات غير صالحة" }
      ]
    }
  ]
}

