// server.mjs
// خادم عروض الأسعار — وحدات Node المدمجة فقط (http / fs / path / url) بلا أي اعتماد خارجي.
// يستمع على المنفذ 3000، يخدم index.html عند GET /، ويستقبل POST /api/quote بجسم JSON.

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT = 3000;
const MAX_BODY_BYTES = 1_000_000; // سقف حجم الجسم (بايت) — تجاوزه يعني طلبًا غير صالح

// حدود التحقق الصارم
const LIMITS = Object.freeze({
  ITEMS_MIN: 1,
  ITEMS_MAX: 100,
  UNIT_PRICE_MIN: 0,
  UNIT_PRICE_MAX: 10_000_000,
  QUANTITY_MIN: 1,
  QUANTITY_MAX: 10_000,
  DISCOUNT_MIN: 0,
  DISCOUNT_MAX: 100,
  SHIPPING_MIN: 0,
  SHIPPING_MAX: 1_000_000,
  SUBTOTAL_MAX: 1_000_000_000,
});

const INVALID_BODY = JSON.stringify({ error: 'invalid' });

// كائن عادي فقط (ليس مصفوفة ولا null)
function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// عدد صحيح آمن ضمن مجال — يرفض النصوص وnull وboolean والكسور وNaN وInfinity دون أي تحويل
function isSafeIntBetween(value, min, max) {
  return Number.isSafeInteger(value) && value >= min && value <= max;
}

function sendJson(res, status, bodyText, extraHeaders = {}) {
  if (res.headersSent) return;
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(bodyText),
    ...extraHeaders,
  });
  res.end(bodyText);
}

function replyInvalid(res) {
  sendJson(res, 400, INVALID_BODY); // {"error":"invalid"} بالضبط
}

/**
 * التحقق الصارم من المدخلات ثم الحساب.
 * تُرجع كائن النتيجة عند النجاح، أو null عند أي مخالفة (→ 400).
 */
function validateAndCompute(payload) {
  // الجسم يجب أن يكون كائنًا (وليس مصفوفة أو null أو نصًا أو رقمًا)
  if (!isPlainObject(payload)) return null;

  const items = payload.items;
  const discountPercent = payload.discountPercent;
  const shippingCents = payload.shippingCents;

  // items: مصفوفة طولها من 1 إلى 100
  if (!Array.isArray(items) || items.length < LIMITS.ITEMS_MIN || items.length > LIMITS.ITEMS_MAX) return null;

  // discountPercent: عدد صحيح آمن من 0 إلى 100 (لا تحويل من نص أو null)
  if (!isSafeIntBetween(discountPercent, LIMITS.DISCOUNT_MIN, LIMITS.DISCOUNT_MAX)) return null;

  // shippingCents: عدد صحيح آمن من 0 إلى 1000000
  if (!isSafeIntBetween(shippingCents, LIMITS.SHIPPING_MIN, LIMITS.SHIPPING_MAX)) return null;

  const seenSkus = new Set(); // كشف التكرار بمقارنة القيم بعد trim
  let subtotalCents = 0;

  for (const item of items) {
    if (!isPlainObject(item)) return null;

    const sku = item.sku;
    const unitPriceCents = item.unitPriceCents;
    const quantity = item.quantity;

    // sku: نص غير فارغ بعد trim
    if (typeof sku !== 'string') return null;
    const trimmedSku = sku.trim();
    if (trimmedSku.length === 0) return null;
    if (seenSkus.has(trimmedSku)) return null;
    seenSkus.add(trimmedSku);

    // unitPriceCents: عدد صحيح آمن من 0 إلى 10000000
    if (!isSafeIntBetween(unitPriceCents, LIMITS.UNIT_PRICE_MIN, LIMITS.UNIT_PRICE_MAX)) return null;

    // quantity: عدد صحيح آمن من 1 إلى 10000
    if (!isSafeIntBetween(quantity, LIMITS.QUANTITY_MIN, LIMITS.QUANTITY_MAX)) return null;

    // أقصى مجموع ممكن أثناء الجمع: 100 × (10000000 × 10000) = 1e13 < 2^53 (عدد آمن، لا فيض)
    subtotalCents += unitPriceCents * quantity;
  }

  // مجموع الأسعار قبل الخصم يجب ألا يتجاوز 1000000000 سنت
  if (subtotalCents > LIMITS.SUBTOTAL_MAX) return null;

  // discountCents = تقريب subtotalCents × discountPercent ÷ 100 إلى الأقرب مع النصف للأعلى
  // (نفس دلالة Math.floor(x + 0.5)؛ حاصل الضرب عدد آمن ≤ 1e11 فالحساب دقيق بلا أخطاء الفاصلة العائمة)
  const discountCents = Math.floor((subtotalCents * discountPercent) / 100 + 0.5);

  // الشحن لا يدخل في حساب الخصم
  const totalCents = subtotalCents - discountCents + shippingCents;

  // الحقول الأربعة فقط
  return { subtotalCents, discountCents, shippingCents, totalCents };
}

// POST /api/quote
function handleQuote(req, res) {
  const chunks = [];
  let receivedBytes = 0;
  let rejected = false;

  req.on('data', (chunk) => {
    if (rejected) return; // بعد الرفض نتجاهل بقية الجسم (تصريف فقط)
    receivedBytes += chunk.length;
    if (receivedBytes > MAX_BODY_BYTES) {
      rejected = true;
      chunks.length = 0;
      replyInvalid(res);
      return;
    }
    chunks.push(chunk);
  });

  req.on('end', () => {
    if (rejected) return;
    let parsed;
    try {
      // JSON معطوب أو فارغ → 400
      parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    } catch {
      replyInvalid(res);
      return;
    }
    const result = validateAndCompute(parsed);
    if (result === null) {
      replyInvalid(res); // مدخل مخالف أو الجسم ليس كائنًا → 400 {"error":"invalid"}
      return;
    }
    sendJson(res, 200, JSON.stringify(result)); // نجاح 200 بالحقول الأربعة فقط
  });

  req.on('error', () => {
    if (!rejected) replyInvalid(res);
  });
}

// GET / أو GET /index.html → ملف الواجهة
function serveIndex(req, res) {
  const filePath = path.join(__dirname, 'index.html');
  fs.readFile(filePath, (err, data) => {
    if (err) {
      sendJson(res, 404, JSON.stringify({ error: 'not found' }));
      return;
    }
    if (res.headersSent) return;
    res.writeHead(200, {
      'Content-Type': 'text/html; charset=utf-8',
      'Content-Length': data.length,
    });
    res.end(req.method === 'HEAD' ? undefined : data);
  });
}

const server = http.createServer((req, res) => {
  res.on('error', () => {}); // منع انهيار الخادم عند انقطاع العميل
  try {
    const urlPath = (req.url || '/').split('?')[0];

    if (urlPath === '/api/quote') {
      if (req.method === 'POST') {
        handleQuote(req, res);
      } else {
        sendJson(res, 405, INVALID_BODY, { Allow: 'POST' });
      }
      return;
    }

    if (req.method === 'GET' || req.method === 'HEAD') {
      if (urlPath === '/' || urlPath === '/index.html') {
        serveIndex(req, res);
      } else {
        sendJson(res, 404, JSON.stringify({ error: 'not found' }));
      }
      return;
    }

    sendJson(res, 404, JSON.stringify({ error: 'not found' }));
  } catch {
